 assert.equal(images.get('A')!.id,images.get('B')!.id);const conversationId=randomUUID();for(const user of[f.a,f.b])await f.checked(user.token,'/api/conversations','POST',{id:conversationId});for(const[user,owner]of[[f.a,'A'],[f.b,'B']]as const){const id=randomUUID();await f.checked(user.token,'/api/query-runs','POST',{id,input:{question:'Observe generated image',attachmentIds:[images.get(owner)!.id],conversationId}});const result=await f.wait(user,id);assert.equal(result.status,'completed',JSON.stringify(result));assert.equal(result.result.citations[0].id,images.get(owner)!.id);assert.ok(f.requests.filter(request=>request.owner===owner).some(request=>request.raw.includes(images.get(owner)!.bytes.toString('base64'))));assert.ok(f.requests.filter(request=>request.owner===owner).every(request=>!request.raw.includes(images.get(owner==='A'?'B':'A')!.bytes.toString('base64'))));}
