 const gate=deferred(),entered=deferred(),positiveEntered=deferred();t.after(()=>gate.resolve());let future='';
 const report=(body:any,raw:string,res:ServerResponse,owner:string)=>{const uses=body.messages.flatMap((message:any)=>Array.isArray(message.content)?message.content.filter((part:any)=>part.type==='tool_use'):[]);if(!uses.some((use:any)=>use.name==='material_read'))return respond(body,raw,res,owner);const original=raw.match(/capture:([0-9a-f-]{36})/)?.[1];assert.ok(original);writeMessagesResponse(res,{stage:uses.length+1,text:JSON.stringify({answer:JSON.stringify({title:'Generated automatic Insight '+owner,markdown:'Generated fixed report '+owner+' ['+original+']',html:'<main>Generated fixed report '+owner+' ['+original+']</main>'}),citationIds:[original]})});};
 f.scripts.set('A',async(body,raw,res)=>{assert.ok(!raw.includes('GENERATED_B_PRIVATE_ORIGINAL'));assert.ok(!raw.includes('GENERATED_FUTURE_WINDOW_BODY'));if(raw.includes('Host policy '+id+' ')){entered.resolve();await gate.promise;return writeMessagesResponse(res,{stage:1,text:JSON.stringify({answer:'Generated forbidden late scheduled Insight A',citationIds:[]})});}positiveEntered.resolve();await gate.promise;report(body,raw,res,'A');});f.scripts.set('B',(body,raw,res)=>{assert.ok(!raw.includes('GENERATED_A_PRIVATE_ORIGINAL'));report(body,raw,res,'B');});
 await delay(61000);const context=await f.node.authority.authenticate(f.a.token);f.node.ask!.automations.wake(context);await Promise.all([entered.promise,positiveEntered.promise]);const snapshot=f.read(db=>JSON.parse(String(db.prepare('SELECT plan FROM ma_auto_windows WHERE user_id=? AND policy_id=?').get(f.a.userId,positive)!.plan)));assert.ok(snapshot.snapshot.materials.length);const futureMaterial=await f.publish(f.a,'A','same-source','future-same-source','GENERATED_FUTURE_WINDOW_BODY');future=futureMaterial.id;assert.ok(!snapshot.snapshot.materials.some((pin:any)=>pin.id===future));
 await f.replace(f.a.token,'models',{profiles:[{id:'same-model',name:'Changed after window',settings:{...defaultModelSettings(),provider:'custom',protocol:'anthropic-messages',model:'generated-new-selection',baseUrl:f.modelUrl,apiKey:'GENERATED_A_KEY',headers:{},extraBody:{}}}],selections:{chat:{kind:'personal',id:'same-model'},insight:{kind:'personal',id:'same-model'},memory:{kind:'personal',id:'same-model'}}});await f.checked(f.a.token,'/api/ask-automations/'+id+'/stop','POST',{});gate.resolve();
 const deadline=Date.now()+20000;for(;;){const a=await f.checked(f.a.token,'/api/ask-automations/'+positive),b=await f.checked(f.b.token,'/api/ask-automations/'+positive);if(a.windows.some((window:any)=>window.state==='completed')&&b.windows.some((window:any)=>window.state==='completed'))break;if(Date.now()>deadline)assert.fail(JSON.stringify({a,b,tasks:f.read(db=>db.prepare('SELECT kind,state,error FROM execution_steps').all())}));await delay(20);}
 assert.equal(f.read(db=>db.prepare("SELECT count(*) n FROM ma_runs WHERE user_id=? AND mode='insight' AND status='completed'").get(f.a.userId)!.n),1);const result=await f.checked(f.a.token,'/api/insights');assert.equal(result.items.length,1);assert.ok(result.items[0].artifact.html.includes('Generated fixed report A'));assert.equal(result.items[0].citations.length,1);assert.ok(f.requests.filter(request=>request.owner==='A').every(request=>request.body.model==='generated-ask'));const count=f.requests.length;await f.restart();await delay(300);assert.equal(f.requests.length,count,'successful Insight windows do not replay after restart');assert.equal(f.read(db=>db.prepare('SELECT count(*) n FROM ma_turns WHERE user_id=?').get(f.a.userId)!.n),1);assert.equal((await f.checked(f.a.token,'/api/ask-automations/'+id)).state,'stopped');
