test('periodic working pause and restart keep its original grant, retry finite failed fragments, and stop requires fresh owner admission',async t=>{
 const f=await fixture(t),settings=defaultMemorySettings();settings.automatic=false;settings.lifecycle.recentTurns=2;settings.lifecycle.working={enabled:true,intervalHours:1,minChanges:1,maxItems:20};await f.replace(f.a.token,'memory',settings);const gate=deferred(),entered=deferred();t.after(()=>gate.resolve());let compactCalls=0,held=true,fail=true;f.scripts.set('A',(_body,raw,res)=>{if(raw.includes('Compact this conversation, preserving')){compactCalls++;if(held){entered.resolve();void gate.promise.then(()=>writeMessagesResponse(res,{stage:1,text:JSON.stringify({answer:'Generated revoked first attempt',citationIds:[]})}));return;}if(fail){res.statusCode=400;res.end('Generated permanent synthetic rejection');return;}return writeMessagesResponse(res,{stage:1,text:JSON.stringify({answer:'Generated resumed policy summary',citationIds:[]})});}writeMessagesResponse(res,{stage:1,text:JSON.stringify({answer:'Generated ordinary context',citationIds:[]})});});
 const conversation=randomUUID();await f.checked(f.a.token,'/api/conversations','POST',{id:conversation});for(let i=0;i<3;i++){const id=randomUUID();await f.checked(f.a.token,'/api/query-runs','POST',{id,input:{question:'Generated policy input '+i,conversationId:conversation}});assert.equal((await f.wait(f.a,id)).status,'completed');}const id=randomUUID();await f.checked(f.a.token,'/api/ask-automations','POST',{id,kind:'working',conversationId:conversation,includeExisting:true});await entered.promise;const before=await f.checked(f.a.token,'/api/ask-automations/'+id);await f.checked(f.a.token,'/api/ask-automations/'+id+'/pause','POST',{});gate.resolve();await f.restart();assert.equal((await f.checked(f.a.token,'/api/ask-automations/'+id)).state,'paused');assert.equal((await f.checked(f.a.token,'/api/conversations/'+conversation)).summary,undefined);held=false;await f.checked(f.a.token,'/api/ask-automations/'+id+'/resume','POST',{});
 const deadline=Date.now()+15000;let child='';for(;;){child=f.read(db=>String(db.prepare('SELECT run_id FROM ma_auto_runs WHERE user_id=? AND policy_id=?').get(f.a.userId,id)?.run_id??''));if(child&&(await f.checked(f.a.token,'/api/query-runs/'+child)).status==='failed')break;assert.ok(Date.now()<deadline);await delay(20);}fail=false;await f.checked(f.a.token,'/api/ask-automations/'+id+'/retry','POST',{});assert.equal((await f.wait(f.a,child)).status,'completed');const after=await f.checked(f.a.token,'/api/ask-automations/'+id);assert.equal(after.generation,before.generation);assert.equal(after.task_id,before.task_id);assert.equal((await f.checked(f.a.token,'/api/conversations/'+conversation)).summary.text,'Generated resumed policy summary');assert.equal(compactCalls,3);await f.checked(f.a.token,'/api/ask-automations/'+id+'/stop','POST',{});assert.equal((await f.request(f.a.token,'/api/ask-automations/'+id+'/pause','POST',{})).statusCode,409);const fresh=await f.checked(f.a.token,'/api/ask-automations','POST',{id,kind:'working',conversationId:conversation,includeExisting:true});assert.notEqual(fresh.generation,before.generation);assert.notEqual(fresh.task_id,before.task_id);
});

test('a durable domain task or generic task payload cannot mint another periodic owner policy grant',async t=>{
 const f=await fixture(t),id=randomUUID(),policy=await f.checked(f.a.token,'/api/ask-automations','POST',{id,kind:'working'}),duplicate=await f.checked(f.a.token,'/api/ask-automations','POST',{id,kind:'working'});assert.equal(duplicate.task_id,policy.task_id);const forged=await f.request(f.a.token,'/api/tasks','POST',{kind:'ask.automation',operationId:'generated-extra-policy-grant',input:{id,generation:policy.generation}});assert.equal(forged.statusCode,409,forged.body);
 const dispose=f.node.execution!.register({kind:'generated-policy-boundary-test',pool:'generated-policy-boundary-test',concurrency:()=>1,policy:{timeoutMs:10000,maxAttempts:1,maxRecoveryWindowMs:null},parseInput:()=>({}),execute:async run=>{assert.throws(()=>f.node.ask!.automations.forUser(run.context),/ask_automation_owner_required/);return {denied:true};}});t.after(dispose);const task=await f.checked(f.a.token,'/api/tasks','POST',{kind:'generated-policy-boundary-test',operationId:randomUUID(),input:{}}),deadline=Date.now()+5000;for(;;){const result=await f.checked(f.a.token,'/api/tasks/'+task.id);if(result.state==='succeeded')break;assert.ok(Date.now()<deadline,JSON.stringify(result));await delay(20);}assert.equal(f.read(db=>db.prepare("SELECT count(*) n FROM user_tasks t JOIN execution_steps e ON e.id=t.task_id WHERE t.user_id=? AND e.kind='ask.automation'").get(f.a.userId)!.n),1);assert.equal(f.requests.length,0);
});

test('scoped Insight preserves the existing measured snapshot and version contract without foreign coverage',async t=>{
 const f=await fixture(t),settings=defaultMemorySettings();settings.automatic=false;await f.replace(f.a.token,'memory',settings);await f.replace(f.b.token,'memory',settings);await f.publish(f.a,'A');await f.publish(f.b,'B');
 for(const user of [f.a,f.b])await f.checked(user.token,'/api/ingress/sources','POST',{id:'paused-'+user.userId,name:'Generated paused source',kind:'custom',deviceId:'same-device',platform:'import',retention:'snapshot',enabled:false});
 for(const [user,device,source,duration] of [[f.a,'activity-a1','activity-a1',2000],[f.a,'activity-a2','activity-a2',2000],[f.b,'activity-b','activity-b',9000]] as const){await f.checked(user.token,'/api/ingress/sources','POST',{id:source,name:'Generated sampling',kind:'custom',deviceId:device,platform:'import',retention:'snapshot'});await f.checked(user.token,'/api/ingress/sources/'+source+'/captures','POST',{batchId:'sampling',items:[{id:randomUUID(),deviceId:device,deviceName:'Generated sampling',platform:'import',capturedAt:'2026-01-01T00:00:05Z',durationMs:duration,source:'activity',appId:'generated.app',appName:'Generated app',windowTitle:'',ocrText:'',privacy:{excluded:false,redacted:false,mode:'local',collection:'activity'}}]});}
 f.scripts.set('A',(body,raw,res)=>{assert.ok(!raw.includes('GENERATED_B_PRIVATE_ORIGINAL'));const uses=body.messages.flatMap((message:any)=>Array.isArray(message.content)?message.content.filter((part:any)=>part.type==='tool_use'):[]);if(!uses.some((use:any)=>use.name==='material_read'))return respond(body,raw,res,'A');const original=raw.match(/capture:([0-9a-f-]{36})/)?.[1];assert.ok(original);writeMessagesResponse(res,{stage:uses.length+1,text:JSON.stringify({answer:JSON.stringify({title:'Generated measured review',markdown:'Generated reviewed fact ['+original+']',html:'<main>Generated reviewed fact ['+original+']</main>'}),citationIds:[original]})});});
 const ready=Date.now()+10000;while(f.read(db=>Number(db.prepare("SELECT count(*) n FROM execution_steps WHERE kind='memory.materials' AND state IN('waiting','running')").get()!.n))){assert.ok(Date.now()<ready);await delay(10);}
 const input={question:'Generated repeat measured review',after:'2026-01-01T00:00:00Z',before:'2026-01-01T00:00:10Z',timeZone:'UTC'},results:any[]=[];for(let i=0;i<2;i++){const id=randomUUID();await f.checked(f.a.token,'/api/insight-runs','POST',{requestId:id,...input});const run=await f.wait(f.a,id);assert.equal(run.status,'completed',JSON.stringify(run));assert.ok(run.result.snapshot,'the existing InsightSnapshot host coverage must survive the scoped migration');results.push(run.result.snapshot);assert.equal(run.result.snapshot.coverage.measured.observedDurationMs,2000);assert.equal(run.result.snapshot.coverage.measured.deviceDurationMs,4000);assert.equal(run.result.snapshot.coverage.measured.overlapDurationMs,2000);assert.equal(run.result.snapshot.coverage.measured.unobservedDurationMs,8000);assert.ok(!run.result.snapshot.coverage.sourceStates.some((source:any)=>source.id==='activity-b'));assert.ok(run.result.snapshot.coverage.limitations.includes('unobserved_sampling_intervals'));}
 assert.equal(results[0].version,1);assert.equal(results[1].version,2);assert.equal(results[1].previousRunId,results[0].id);assert.equal(results[0].scopeFingerprint,results[1].scopeFingerprint);assert.ok(results[0].coverage.sourceStates.some((source:any)=>source.id==='paused-'+f.a.userId&&source.state==='paused'));assert.ok(!JSON.stringify(results).includes('paused-'+f.b.userId));assert.ok(f.requests.some(request=>request.raw.includes('hostInsightSnapshot')&&request.raw.includes('observed_intervals_only')));const clippedId=randomUUID();await f.checked(f.a.token,'/api/insight-runs','POST',{requestId:clippedId,...input,before:'2026-01-01T00:00:04Z'});const clipped=await f.wait(f.a,clippedId);assert.equal(clipped.status,'completed',JSON.stringify(clipped));assert.equal(clipped.result.snapshot.coverage.measured.observedDurationMs,1000,'an original sampled interval crossing the upper boundary is clipped, not discarded');assert.equal(clipped.result.snapshot.coverage.measured.deviceDurationMs,2000);assert.equal(clipped.result.snapshot.coverage.measured.unobservedDurationMs,3000);
 const count=f.requests.length,service=f.node.services.forUser(await f.node.authority.authenticate(f.a.token)),archive=await service.exportUser('ask');await service.deleteUser('ask',randomUUID());assert.equal(f.read(db=>Number(db.prepare('SELECT count(*) n FROM ma_insight_snapshots WHERE user_id=?').get(f.a.userId)!.n)),0);const operation=randomUUID();await service.restoreUser('ask',archive,operation);await service.restoreUser('ask',archive,operation);await f.restart();assert.deepEqual((await f.checked(f.a.token,'/api/query-runs/'+results[1].id)).result.snapshot,results[1]);await delay(100);assert.equal(f.requests.length,count,'static snapshot restoration must not restore execution authority');const versionId=randomUUID();await f.checked(f.a.token,'/api/insight-runs','POST',{requestId:versionId,...input});const next=await f.wait(f.a,versionId);assert.equal(next.status,'completed',JSON.stringify(next));assert.equal(next.result.snapshot.version,3);assert.equal(next.result.snapshot.previousRunId,results[1].id);
});

test('source tombstones remain owner metadata and cannot expand through the query reader',async t=>{
 const f=await fixture(t),settings=defaultMemorySettings();settings.automatic=false;const ids=new Map<string,string[]>();
 for(const user of [f.a,f.b]){await f.replace(user.token,'memory',settings);await f.checked(user.token,'/api/ingress/sources','POST',{id:'same-source',name:'Generated source',kind:'custom',deviceId:'same-device',platform:'import',retention:user===f.a?'archive':'snapshot'});for(const [revision,text,deleted]of [['v1','GENERATED_REMOVED_OLD_BODY',false],['v2','',true]] as const){const receipt=await f.checked(user.token,'/api/ingress/sources/same-source/items','POST',{batchId:revision,items:[{externalId:'same-removed-item',revision,observedAt:'2026-01-01T00:00:00Z',title:'Generated source deletion',kind:'message',layer:'original',text,deleted}]});ids.set(user.userId,[...(ids.get(user.userId)??[]),receipt.captures[0].id]);}const head=await f.checked(user.token,'/api/sources/same-source/item?externalId=same-removed-item');assert.equal(head.item.deleted,true);assert.ok(!JSON.stringify(head).includes('GENERATED_REMOVED_OLD_BODY'));}
 for(const user of [f.a,f.b]){const context=await f.node.authority.authenticate(user.token),reader=f.node.ask!.bind(context,{sourceIds:['same-source'],assertCurrent:()=>{}}).reader();for(const includeDeleted of [false,true])assert.deepEqual((await reader.agent.sourceItems!({sourceId:'same-source',includeDeleted})).items,[],'legacy model query visibility excludes tombstones even when includeDeleted is accepted');for(const id of ids.get(user.userId)!)await assert.rejects(reader.read(['capture:'+id]));}
});

test('native source item kind filters match the canonical record kind while Material catalogs retain their own kind',async t=>{
 const f=await fixture(t),material=await f.publish(f.a,'A'),reader=f.node.ask!.bind(await f.node.authority.authenticate(f.a.token),{sourceIds:['same-source'],assertCurrent:()=>{}}).reader(),all=await reader.agent.sourceItems!({sourceId:'same-source',limit:100}),kind=(all.items[0] as any).source;assert.ok(kind);const expected=all.items.filter(record=>(record as any).source===kind).map(record=>record.id).sort(),filtered=await reader.agent.sourceItems!({sourceId:'same-source',kind,limit:100});assert.deepEqual(filtered.items.map(record=>record.id).sort(),expected,'a returned canonical kind must select the same native records');const catalog=await reader.agent.materialCatalog!({sourceId:'same-source',kind:'document'});assert.ok(catalog.items.some(item=>item.id===material.id));const entities=await reader.browse({sourceId:'same-source',kind:'document'});assert.ok(entities.items.some(item=>item.id===material.id));assert.deepEqual((await reader.agent.sourceItems!({sourceId:'same-source',kind:'document'})).items,[]);
});

test('explicit request model reference and personal model ID preserve own fixed transport without changing feature defaults',async t=>{
 const f=await fixture(t);await f.publish(f.a,'A');
 const view=await f.checked(f.a.token,'/api/configuration'),models=view.domains.find((value:any)=>value.id==='models').effective;
 await f.replace(f.a.token,'models',{...models,profiles:[{id:'same-model',name:'Generated Ask model',settings:{...defaultModelSettings(),provider:'custom',protocol:'anthropic-messages',model:'generated-ask',baseUrl:f.modelUrl,apiKey:'GENERATED_A_KEY',headers:{},extraBody:{}}},{id:'request-only',name:'Generated request-only',settings:{...defaultModelSettings(),provider:'custom',protocol:'anthropic-messages',model:'request-base',baseUrl:f.modelUrl,apiKey:'GENERATED_A_REQUEST_KEY',headers:{},extraBody:{}}}]});
 const before=await f.checked(f.a.token,'/api/models');const id=randomUUID();
 await f.checked(f.a.token,'/api/query-runs','POST',{id,input:{question:'Generated explicit personal model request',modelReference:{kind:'personal',id:'request-only'},modelOverride:'request-override'}});
 assert.equal((await f.wait(f.a,id)).status,'completed');assert.ok(f.requests.length>0);assert.ok(f.requests.every(value=>value.owner==='A'&&value.body.model==='request-override'));
 assert.deepEqual(await f.checked(f.a.token,'/api/models'),before,'per-request selection cannot silently mutate defaults');
 const prior=f.requests.length;
 assert.equal((await f.request(f.b.token,'/api/query-runs','POST',{id:randomUUID(),input:{question:'Generated foreign personal profile',modelReference:{kind:'personal',id:'request-only'}}})).statusCode,400);
 assert.equal((await f.request(f.a.token,'/api/query-runs','POST',{id:randomUUID(),input:{question:'Generated forged endpoint',modelReference:{kind:'personal',id:'request-only',baseUrl:'https://external.invalid'}}})).statusCode,400);
 assert.equal(f.requests.length,prior);
});


test('rechecking disclosed originals keeps the persistent Ask pin journal read-only',async t=>{
 const f=await fixture(t);await f.publish(f.a,'A');
 // A generated audit trigger observes writes through the real Harness. It does
 // not replace account, task, source or receipt validation.
 f.read(db=>db.exec("CREATE TABLE generated_pin_updates(changed INTEGER NOT NULL); CREATE TRIGGER generated_pin_update AFTER UPDATE OF pins,materials ON ma_runs BEGIN INSERT INTO generated_pin_updates VALUES(OLD.pins!=NEW.pins OR OLD.materials!=NEW.materials); END"));
 const id=randomUUID();await f.checked(f.a.token,'/api/query-runs','POST',{id,input:{question:'Generated persistent receipt recheck'}});const result=await f.wait(f.a,id);assert.equal(result.status,'completed',JSON.stringify(result));
 const writes=f.read(db=>db.prepare('SELECT changed,count(*) n FROM generated_pin_updates GROUP BY changed ORDER BY changed').all());
 assert.ok(writes.some(row=>row.changed===1),'first genuine original/material observations must persist');
 assert.equal(writes.filter(row=>row.changed===0).reduce((n,row)=>n+Number(row.n),0),0,'revalidating a retained original must not rewrite identical persistent pins');
 assert.equal(result.result.citations.length,1);assert.equal((await f.request(f.b.token,'/api/query-runs/'+id)).statusCode,404);
});

test('a coordinator waiting for an unchanged real child does not repeatedly claim execution leases',async t=>{
 const f=await delegated(t,{holdSecond:true});f.read(db=>db.exec("CREATE TABLE generated_coordinator_claims(task_id TEXT NOT NULL); CREATE TRIGGER generated_coordinator_claim AFTER UPDATE OF state ON execution_steps WHEN NEW.kind='ask.coordinate' AND NEW.state='running' AND OLD.state!='running' BEGIN INSERT INTO generated_coordinator_claims VALUES(NEW.id); END"));
 const id=randomUUID();await f.checked(f.a.token,'/api/query-runs','POST',{id,input:{question:'Generated unchanged child admission'}});await f.entered.promise;const taskId=f.read(db=>String(db.prepare('SELECT task_id FROM ma_runs WHERE user_id=? AND id=?').get(f.a.userId,id)!.task_id)),claims=()=>f.read(db=>Number(db.prepare('SELECT count(*) n FROM generated_coordinator_claims WHERE task_id=?').get(taskId)!.n)),deadline=Date.now()+5000;
 try{while((await f.checked(f.a.token,'/api/tasks/'+taskId)).state!=='waiting'){assert.ok(Date.now()<deadline,'coordinator did not yield its execution slot');await delay(10);}const before=claims();await delay(400);assert.equal(claims(),before,'an unchanged pending child is admission waiting, not fresh coordinator execution');}finally{f.gate.resolve();}
 const result=await f.wait(f.a,id);assert.equal(result.status,'completed',JSON.stringify(result));assert.deepEqual(f.childStarts,{one:1,two:1});assert.equal(result.result.citations[0].id,f.canonical);
});
